pub fn run<'a>(
    config: &'a aws_config::SdkConfig,
    operation: &'a str,
    input: &'a Value,
    options: &'a Options,
) -> core::CommandFuture<'a> {
    Box::pin(async move {
        let mut config = aws_sdk_sts::config::Builder::from(config);
        if let Some(endpoint) = &options.endpoint_url {
            config = config.endpoint_url(endpoint);
        }
        let client = aws_sdk_sts::Client::from_conf(config.build());
        let output = Output::new(options.clone());
        let command: core::CommandFuture<'_> = match operation {
            "assume_role" => Box::pin(call_assume_role(&client, input, &output)),
            "assume_role_with_saml" => {
                Box::pin(call_assume_role_with_saml(&client, input, &output))
            }
            "assume_role_with_web_identity" => {
                Box::pin(call_assume_role_with_web_identity(&client, input, &output))
            }
            "assume_root" => Box::pin(call_assume_root(&client, input, &output)),
            "decode_authorization_message" => {
                Box::pin(call_decode_authorization_message(&client, input, &output))
            }
            "get_access_key_info" => Box::pin(call_get_access_key_info(&client, input, &output)),
            "get_caller_identity" => Box::pin(call_get_caller_identity(&client, input, &output)),
            "get_delegated_access_token" => {
                Box::pin(call_get_delegated_access_token(&client, input, &output))
            }
            "get_federation_token" => Box::pin(call_get_federation_token(&client, input, &output)),
            "get_session_token" => Box::pin(call_get_session_token(&client, input, &output)),
            "get_web_identity_token" => {
                Box::pin(call_get_web_identity_token(&client, input, &output))
            }
            _ => return Err(CliError::input(format!("unknown operation: {operation}"))),
        };
        command
            .await
            .map_err(|error| error.context("sts", operation))
    })
}
